<?php require_once __DIR__.'/includes/config.php'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$phone=trim($_POST['phone']??'');$pass=$_POST['password']??'';if(!$name||!$email||!$phone||strlen($pass)<8){$error='Enter valid details. Password must contain at least 8 characters.';}else{try{$s=$pdo->prepare('INSERT INTO users(full_name,email,phone,password_hash) VALUES(?,?,?,?)');$s->execute([$name,$email,$phone,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['user_id']=(int)$pdo->lastInsertId();$_SESSION['user_name']=$name;header('Location: dashboard.php');exit;}catch(PDOException $ex){$error='This email may already be registered.';}}} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register | Ladle Loan</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="form-wrap"><form class="form-card" method="post"><a href="index.php">← Ladle Loan</a><h1>Create applicant account</h1><p>Register to submit and track your academic demo application.</p><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Full name<input name="name" required maxlength="100"></label><label>Email<input type="email" name="email" required></label><label>Phone<input name="phone" required maxlength="20"></label><label>Password<input type="password" name="password" minlength="8" required></label><button class="btn">Create account</button><p>Already registered? <a href="login.php">Login</a></p></form></div></body></html>